package com.docgen.service

import kotlinx.coroutines.*
import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import java.util.UUID

data class TemplateAsset(
    val originalName: String,
    val contentType: String,
    val data: ByteArray,
    val checksum: String
)

data class RenderJob(
    val jobId: String,
    val templateId: String,
    val assets: List<TemplateAsset>,
    val outputPath: String
)

object MimeValidator {
    private val ALLOWED_MIMES = setOf(
        "image/png", "image/jpeg", "image/svg+xml",
        "application/pdf", "font/ttf", "font/otf"
    )

    fun isAllowed(contentType: String): Boolean {
        return contentType.lowercase() in ALLOWED_MIMES
    }
}

object PathSanitizer {
    private val TRAVERSAL_PATTERN = Regex("""\.\./|\.\.\\\\""")
    private val BANNED_CHARS = setOf('\u0000', '|', ';', '&', '`', '$')

    fun sanitize(filename: String): String {
        var clean = filename.replace(TRAVERSAL_PATTERN, "")
        clean = clean.filter { it !in BANNED_CHARS }
        return clean.takeLastWhile { it != '/' && it != '\\' }
    }

    fun isWithinBase(resolved: Path, base: Path): Boolean {
        return resolved.normalize().startsWith(base.normalize())
    }
}

object ContentInspector {
    private val PNG_MAGIC = byteArrayOf(0x89.toByte(), 0x50, 0x4E, 0x47)
    private val JPEG_MAGIC = byteArrayOf(0xFF.toByte(), 0xD8.toByte(), 0xFF.toByte())
    private val PDF_MAGIC = "%PDF".toByteArray()

    fun detectType(data: ByteArray): String? {
        if (data.size < 4) return null
        return when {
            data.slice(0..3).toByteArray().contentEquals(PNG_MAGIC) -> "image/png"
            data.slice(0..2).toByteArray().contentEquals(JPEG_MAGIC) -> "image/jpeg"
            data.slice(0..3).toByteArray().contentEquals(PDF_MAGIC) -> "application/pdf"
            data.decodeToString().trimStart().startsWith("<svg") -> "image/svg+xml"
            else -> null
        }
    }
}

class AssetStorageService(private val baseDir: String) {
    private val stagingJobs = ConcurrentHashMap<String, MutableList<Path>>()
    private val basePath = Paths.get(baseDir).toAbsolutePath().normalize()

    init {
        Files.createDirectories(basePath)
    }

    suspend fun stageAsset(jobId: String, asset: TemplateAsset): Result<Path> = coroutineScope {
        val deferred = async(Dispatchers.IO) {
            validateAsset(asset)
        }
        val validationResult = deferred.await()
        if (validationResult.isFailure) {
            return@coroutineScope Result.failure(validationResult.exceptionOrNull()!!)
        }

        val writePath = async(Dispatchers.IO) {
            persistAsset(jobId, asset)
        }
        writePath.await()
    }

    private fun validateAsset(asset: TemplateAsset): Result<Unit> {
        if (!MimeValidator.isAllowed(asset.contentType)) {
            return Result.failure(SecurityException("Disallowed content type: ${asset.contentType}"))
        }

        val detectedType = ContentInspector.detectType(asset.data)
        if (detectedType != null && detectedType != asset.contentType) {
            // Content-type mismatch - but allow if detected type is also allowed
            if (!MimeValidator.isAllowed(detectedType)) {
                return Result.failure(SecurityException("Content inspection failed"))
            }
        }

        val digest = MessageDigest.getInstance("SHA-256")
        val computed = digest.digest(asset.data).joinToString("") { "%02x".format(it) }
        if (computed != asset.checksum) {
            return Result.failure(SecurityException("Checksum mismatch"))
        }

        return Result.success(Unit)
    }

    private fun persistAsset(jobId: String, asset: TemplateAsset): Result<Path> {
        val sanitizedName = PathSanitizer.sanitize(asset.originalName)
        val jobDir = basePath.resolve("jobs").resolve(jobId)
        Files.createDirectories(jobDir)

        val targetPath = jobDir.resolve(sanitizedName).normalize()

        // Security check: ensure we're still within the job directory
        if (!PathSanitizer.isWithinBase(targetPath, jobDir)) {
            return Result.failure(SecurityException("Path traversal detected"))
        }

        // Write the file
        Files.write(targetPath, asset.data)

        stagingJobs.getOrPut(jobId) { mutableListOf() }.add(targetPath)
        return Result.success(targetPath)
    }

    suspend fun finalizeJob(job: RenderJob): Result<Path> = coroutineScope {
        val results = job.assets.map { asset ->
            async { stageAsset(job.jobId, asset) }
        }

        val paths = results.awaitAll()
        val failures = paths.filter { it.isFailure }
        if (failures.isNotEmpty()) {
            // Cleanup on failure
            cleanup(job.jobId)
            return@coroutineScope Result.failure(failures.first().exceptionOrNull()!!)
        }

        // Generate PDF from staged assets
        val outputPath = async(Dispatchers.IO) {
            generatePdf(job)
        }
        outputPath.await()
    }

    private fun generatePdf(job: RenderJob): Result<Path> {
        val outputFile = basePath.resolve("output").resolve("${job.jobId}.pdf")
        Files.createDirectories(outputFile.parent)
        // Simulated PDF generation
        Files.write(outputFile, "%PDF-1.4 generated".toByteArray())
        return Result.success(outputFile)
    }

    private fun cleanup(jobId: String) {
        stagingJobs.remove(jobId)?.forEach { path ->
            try { Files.deleteIfExists(path) } catch (_: Exception) {}
        }
    }
}

class PdfGenerationController(baseDir: String) {
    private val storageService = AssetStorageService(baseDir)

    suspend fun handleUpload(request: RenderJob): Result<Path> {
        if (request.assets.size > 20) {
            return Result.failure(IllegalArgumentException("Too many assets"))
        }
        if (request.assets.any { it.data.size > 10 * 1024 * 1024 }) {
            return Result.failure(IllegalArgumentException("Asset too large"))
        }
        return storageService.finalizeJob(request)
    }
}
